"""Native field guards for live edits against a compiled topology binding.

The immutable indices here are disposable bindings, not persistent street IDs.
They qualify the unchanged straight, planar Section domain before the surface
kernel runs. Unsupported edits suppress the result rather than silently
straightening a path or reading a different edge after a topology change.
"""
import math


def build(sources, carrier, tree):
    """Return one Boolean socket; both geometries are in local metre space."""
    links = tree.links
    serial = 0

    def node(kind, label):
        nonlocal serial
        n = tree.nodes.new(kind)
        n.name = n.label = 'Live input guard / ' + label
        n.location = (-2500 + (serial % 7) * 200, -1800 - (serial // 7) * 160)
        serial += 1
        return n

    def bind(value, socket):
        if hasattr(value, 'node'):
            links.new(value, socket)
        else:
            socket.default_value = value

    def mathop(operation, a, b=None):
        n = node('ShaderNodeMath', operation.lower())
        n.operation = operation
        bind(a, n.inputs[0])
        if b is not None:
            bind(b, n.inputs[1])
        return n.outputs[0]

    def compare(operation, a, b, kind='FLOAT', epsilon=None):
        n = node('FunctionNodeCompare', operation.lower())
        n.data_type = kind
        n.operation = operation
        bind(a, n.inputs['A'])
        bind(b, n.inputs['B'])
        if epsilon is not None:
            n.inputs['Epsilon'].default_value = epsilon
        return n.outputs['Result']

    def both(*values):
        result = values[0]
        for value in values[1:]:
            n = node('FunctionNodeBooleanMath', 'all conditions')
            n.operation = 'AND'
            bind(result, n.inputs[0]); bind(value, n.inputs[1])
            result = n.outputs[0]
        return result

    def either(a, b):
        n = node('FunctionNodeBooleanMath', 'either orientation')
        n.operation = 'OR'
        bind(a, n.inputs[0]); bind(b, n.inputs[1])
        return n.outputs[0]

    def vector(operation, a, b=None):
        n = node('ShaderNodeVectorMath', operation.lower())
        n.operation = operation
        bind(a, n.inputs[0])
        if b is not None:
            bind(b, n.inputs[1])
        return n.outputs['Value' if operation in ('LENGTH', 'DISTANCE', 'DOT_PRODUCT') else 'Vector']

    def named(name, kind='INT'):
        n = node('GeometryNodeInputNamedAttribute', name)
        n.data_type = kind
        n.inputs['Name'].default_value = name
        return n.outputs['Attribute']

    def sample(geometry, value, at, kind='INT', domain='POINT'):
        n = node('GeometryNodeSampleIndex', 'sample ' + domain.lower())
        n.data_type = kind
        n.domain = domain
        n.clamp = False
        bind(geometry, n.inputs['Geometry'])
        bind(value, n.inputs['Value']); bind(at, n.inputs['Index'])
        return n.outputs['Value']

    def xyz(value):
        n = node('ShaderNodeSeparateXYZ', 'coordinates')
        bind(value, n.inputs[0])
        return n.outputs

    def points_of_type(tag):
        n = node('GeometryNodeSeparateGeometry', 'carrier table ' + str(tag))
        n.domain = 'POINT'
        bind(carrier, n.inputs['Geometry'])
        bind(compare('EQUAL', named('s2_record_type'), tag, 'INT'), n.inputs['Selection'])
        return n.outputs['Selection']

    def statistic(geometry, value, operation='Min', domain='POINT'):
        n = node('GeometryNodeAttributeStatistic', operation.lower() + ' over ' + domain.lower())
        n.data_type = 'FLOAT'
        n.domain = domain
        bind(geometry, n.inputs['Geometry']); bind(value, n.inputs['Attribute'])
        return n.outputs[operation]

    def count(geometry):
        n = node('GeometryNodeAttributeDomainSize', 'table length')
        n.component = 'MESH'
        bind(geometry, n.inputs['Geometry'])
        return n.outputs['Point Count']

    position = node('GeometryNodeInputPosition', 'position').outputs[0]
    index = node('GeometryNodeInputIndex', 'row index').outputs[0]
    paths = points_of_type(1)
    header = points_of_type(0)
    connector_rows = points_of_type(4)
    member_rows = points_of_type(5)

    # Every path vertex must stay on its directed, strictly increasing Section.
    # Test every edge through its starting vertex, so ignored middle vertices
    # cannot introduce a bend or double back unnoticed by the legacy kernel.
    at = named('st_live_vertex_index')
    start_at = named('st_live_start_index')
    end_at = named('st_live_end_index')
    next_at = named('st_live_next_index')
    source_pos = lambda i: sample(sources, position, i, 'FLOAT_VECTOR')
    p, start, end, following = [source_pos(i) for i in (at, start_at, end_at, next_at)]
    delta = vector('SUBTRACT', end, start)
    direction = vector('NORMALIZE', delta)
    relative = vector('SUBTRACT', p, start)
    advance = vector('DOT_PRODUCT', vector('SUBTRACT', following, p), direction)
    distance = vector('LENGTH', vector('CROSS_PRODUCT', relative, direction))
    junction = sample(header, named('s2_junction_position', 'FLOAT_VECTOR'), 0, 'FLOAT_VECTOR')
    point_ok = both(
        compare('EQUAL', sample(sources, named('st_live_vertex_index'), at), at, 'INT'),
        compare('EQUAL', sample(sources, named('st_endpoint_role'), at), named('st_live_endpoint_role'), 'INT'),
        compare('GREATER_THAN', vector('LENGTH', delta), 1.e-6),
        compare('LESS_EQUAL', distance, 1.e-5),
        compare('LESS_EQUAL', mathop('ABSOLUTE', mathop('SUBTRACT', xyz(p)['Z'], xyz(junction)['Z'])), 1.e-6),
        either(compare('EQUAL', at, end_at, 'INT'), compare('GREATER_THAN', advance, 1.e-8)),
        either(compare('NOT_EQUAL', at, end_at, 'INT'), compare('EQUAL', next_at, end_at, 'INT')),
    )
    path_valid = compare('GREATER_THAN', statistic(paths, point_ok), .5)

    # A Street can meet the next junction's Section at an explicitly compiled
    # midspan seam. Its two authored endpoints remain separate source vertices,
    # but their generated cross-sections must coincide before welding.
    seam_at = named('st_live_seam_index')
    has_seam = compare('GREATER_EQUAL', seam_at, 0, 'INT')
    own_neighbor = source_pos(named('st_live_own_neighbor_index'))
    other = source_pos(seam_at)
    other_neighbor = source_pos(named('st_live_seam_neighbor_index'))
    own_direction = vector('NORMALIZE', vector('SUBTRACT', own_neighbor, p))
    other_direction = vector('NORMALIZE', vector('SUBTRACT', other_neighbor, other))
    own_edge = named('st_live_own_edge_index')
    other_edge = named('st_live_seam_edge_index')
    own_width = sample(sources, named('st_width', 'FLOAT'), own_edge, 'FLOAT', 'EDGE')
    other_width = sample(sources, named('st_width', 'FLOAT'), other_edge, 'FLOAT', 'EDGE')
    own_offset = sample(sources, named('st_offset', 'FLOAT'), own_edge, 'FLOAT', 'EDGE')
    other_offset = sample(sources, named('st_offset', 'FLOAT'), other_edge, 'FLOAT', 'EDGE')
    seam_ok = both(
        compare('LESS_EQUAL', vector('DISTANCE', p, other), 1.e-6),
        compare('LESS_EQUAL', vector('DOT_PRODUCT', own_direction, other_direction), -1. + 1.e-6),
        compare('LESS_EQUAL', mathop('ABSOLUTE', mathop('SUBTRACT', own_width, other_width)), 1.e-6),
        compare('LESS_EQUAL', mathop('ABSOLUTE', mathop('SUBTRACT', own_offset,
                mathop('MULTIPLY', other_offset, named('st_live_seam_offset_sign')))), 1.e-6),
    )
    seam_valid = compare('GREATER_THAN', statistic(paths,
        either(compare('EQUAL', has_seam, False, 'INT'), seam_ok)), .5)

    # Bind source edges by their explicit disposable IDs, not collection or
    # Blender mesh numbering. Constant Section values remain an enforced part
    # of this first input contract while changes to the values themselves live.
    edge_at = named('st_live_edge_index')
    first_edge = named('st_live_first_edge_index')
    edge_sample = lambda value, at=edge_at, kind='INT': sample(sources, value, at, kind, 'EDGE')
    width = edge_sample(named('st_width', 'FLOAT'), kind='FLOAT')
    offset = edge_sample(named('st_offset', 'FLOAT'), kind='FLOAT')
    edge_vertices = node('GeometryNodeInputMeshEdgeVertices', 'actual source connectivity')
    v0 = edge_sample(edge_vertices.outputs['Vertex Index 1'])
    v1 = edge_sample(edge_vertices.outputs['Vertex Index 2'])
    id0 = sample(sources, named('st_live_vertex_index'), v0)
    id1 = sample(sources, named('st_live_vertex_index'), v1)
    expected0, expected1 = named('st_live_v0'), named('st_live_v1')
    connectivity = either(
        both(compare('EQUAL', id0, expected0, 'INT'), compare('EQUAL', id1, expected1, 'INT')),
        both(compare('EQUAL', id0, expected1, 'INT'), compare('EQUAL', id1, expected0, 'INT')),
    )
    edge_ok = both(
        compare('EQUAL', edge_sample(named('st_live_edge_index')), edge_at, 'INT'),
        compare('EQUAL', edge_sample(named('st_section_id')), named('st_live_section_id'), 'INT'),
        compare('GREATER_THAN', width, 0.),
        compare('LESS_EQUAL', mathop('ABSOLUTE', mathop('SUBTRACT', width,
                edge_sample(named('st_width', 'FLOAT'), first_edge, 'FLOAT'))), 1.e-6),
        compare('LESS_EQUAL', mathop('ABSOLUTE', mathop('SUBTRACT', offset,
                edge_sample(named('st_offset', 'FLOAT'), first_edge, 'FLOAT'))), 1.e-6),
        connectivity,
    )
    edge_valid = compare('GREATER_THAN', statistic(carrier, edge_ok, domain='EDGE'), .5)

    # A set of individually positive corner angles can still wind around more
    # than once when five or more approaches are reordered. Require one turn.
    def tangent(connector_index):
        member = sample(connector_rows, named('s2_member_start'), connector_index)
        endpoint = sample(member_rows, named('s2_endpoint_vertex'), member)
        nextpoint = sample(member_rows, named('s2_next_vertex'), member)
        a = sample(carrier, position, endpoint, 'FLOAT_VECTOR')
        b = sample(carrier, position, nextpoint, 'FLOAT_VECTOR')
        return vector('NORMALIZE', vector('SUBTRACT', b, a))

    a = tangent(index)
    b = tangent(mathop('FLOORED_MODULO', mathop('ADD', index, 1.), count(connector_rows)))
    angle = mathop('ARCTAN2', xyz(vector('CROSS_PRODUCT', a, b))['Z'], vector('DOT_PRODUCT', a, b))
    ccw = mathop('FLOORED_MODULO', angle, math.tau)
    winding = statistic(connector_rows, ccw, 'Sum')
    winding_valid = compare('LESS_EQUAL', mathop('ABSOLUTE', mathop('SUBTRACT', winding, math.tau)), 1.e-4)
    return both(path_valid, edge_valid, winding_valid, seam_valid)
